style.css:
@-moz-document domain("youtube.com") {
body {
    background-color: #0a0e1a !important;
    color: #e0e0e0 !important;
  }

  /* Header Bar */
  #masthead-container, ytd-masthead {
    background: linear-gradient(90deg, #1e1e3f, #0d1830, #002f5f) !important;
    border-bottom: 2px solid #e63e00 !important;
  }

  /* Logo tint */
  #logo-icon {
    filter: hue-rotate(15deg) saturate(1.5);
  }

  /* Buttons */
  #buttons ytd-button-renderer {
    background: linear-gradient(90deg, #ff7b00, #e60000) !important;
    border-radius: 8px !important;
  }

  /* Sidebar */
  #guide-content {
    background: #0d1220 !important;
  }

  /* Thumbnails */
  ytd-thumbnail {
    border-radius: 10px !important;
    overflow: hidden;
  }

  /* Progress bar */
  .ytp-play-progress {
    background-color: #ff7b00 !important;
  }

  /* Links */
  a, .yt-simple-endpoint {
    color: #ff4800 !important;
  }

  /* Hover effect */
  a:hover {
    color: #ff9d00 !important;
  }
}
